        }
      ],
      "omitempty": true
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "filename": {
      "description": "The filename for display purposes.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    }
  }
}

